import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { motion } from "framer-motion";
import { KeyRound, Mail, Eye, EyeOff, ShieldCheck, User } from "lucide-react";
import { useAuth } from "../context/AuthContext";

function formatApiErrorDetail(detail) {
  if (detail == null) return "Terjadi kesalahan. Silakan coba lagi.";
  if (typeof detail === "string") return detail;
  if (Array.isArray(detail))
    return detail.map((e) => (e && typeof e.msg === "string" ? e.msg : JSON.stringify(e))).filter(Boolean).join(" ");
  if (detail && typeof detail.msg === "string") return detail.msg;
  return String(detail);
}

export default function Login() {
  const { login } = useAuth();
  const nav = useNavigate();
  const [email, setEmail] = useState("admin@lewihouse.com");
  const [password, setPassword] = useState("lewi2026");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const doLogin = async (ident, pass) => {
    setError("");
    setBusy(true);
    try {
      await login(ident, pass);
      nav("/");
    } catch (err) {
      setError(formatApiErrorDetail(err.response?.data?.detail) || err.message || "Gagal masuk.");
    } finally {
      setBusy(false);
    }
  };

  const submit = async (e) => {
    e.preventDefault();
    await doLogin(email, password);
  };

  const quickLoginAdmin = () => {
    setEmail("admin@lewihouse.com");
    setPassword("lewi2026");
    doLogin("admin@lewihouse.com", "lewi2026");
  };

  const quickLoginTenant = () => {
    setEmail("204");
    setPassword("LewiHouse2026!");
    doLogin("204", "LewiHouse2026!");
  };

  return (
    <div className="min-h-screen bg-[#1A362B] flex flex-col justify-end" data-testid="login-page">
      <div className="px-8 pt-16 pb-10 text-white max-w-md mx-auto w-full">
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
          <div className="w-12 h-12 rounded-2xl bg-[#D4AF37]/20 border border-[#D4AF37]/40 grid place-items-center mb-6 shadow-lg">
            <KeyRound size={22} className="text-[#D4AF37]" />
          </div>
          <p className="text-[10px] uppercase tracking-[0.3em] text-[#D4AF37] font-semibold">Manajemen Kosan Boutique</p>
          <h1 className="font-serif text-4xl mt-2 leading-tight">Lewi House</h1>
          <p className="text-sm text-white/70 mt-2">Masuk untuk mengelola kamar, penghuni, tagihan & operasional.</p>
        </motion.div>
      </div>

      <motion.div
        initial={{ y: 40, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ delay: 0.1 }}
        className="bg-[#FBF9F4] rounded-t-[2rem] px-8 pt-8 pb-12 max-w-md mx-auto w-full shadow-2xl"
      >
        <form onSubmit={submit}>
          <label className="block mb-4">
            <span className="text-xs font-bold text-[#1A362B]/70 uppercase tracking-wider mb-1.5 block">Email / ID Kamar</span>
            <div className="relative">
              <Mail size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
              <input
                type="text"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="admin@lewihouse.com atau 204"
                data-testid="login-email-input"
                className="w-full bg-white border border-gray-200 rounded-xl pl-11 pr-4 py-3.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#1A362B] transition-all"
              />
            </div>
          </label>

          <label className="block mb-2">
            <span className="text-xs font-bold text-[#1A362B]/70 uppercase tracking-wider mb-1.5 block">Password</span>
            <div className="relative">
              <input
                type={showPw ? "text" : "password"}
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                data-testid="login-password-input"
                className="w-full bg-white border border-gray-200 rounded-xl px-4 pr-11 py-3.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#1A362B] transition-all"
              />
              <button
                type="button"
                onClick={() => setShowPw(!showPw)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 p-1"
                data-testid="toggle-password-btn"
              >
                {showPw ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            </div>
          </label>

          {error && (
            <div className="p-3 bg-red-50 border border-red-200 rounded-xl mt-3 mb-1">
              <p className="text-xs text-red-600 font-medium" data-testid="login-error">
                {error}
              </p>
            </div>
          )}

          <button
            type="submit"
            disabled={busy}
            data-testid="login-submit-btn"
            className="w-full mt-5 rounded-xl bg-[#1A362B] text-white py-3.5 text-sm font-bold tracking-wide shadow-md active:scale-[0.98] transition-all disabled:opacity-60 hover:bg-[#13271F]"
          >
            {busy ? "Memproses..." : "Masuk ke Sistem"}
          </button>
        </form>

        {/* Quick Demo Access Bar */}
        <div className="mt-8 pt-6 border-t border-gray-200">
          <p className="text-[11px] font-bold uppercase tracking-wider text-gray-500 text-center mb-3">
            ⚡ Akses Cepat (Demo Presets)
          </p>
          <div className="grid grid-cols-2 gap-2.5">
            <button
              type="button"
              onClick={quickLoginAdmin}
              disabled={busy}
              className="flex items-center justify-center gap-1.5 py-2.5 px-3 bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 rounded-xl text-emerald-800 text-xs font-semibold transition-all active:scale-95"
            >
              <ShieldCheck size={14} className="text-emerald-700" />
              <span>Admin / Owner</span>
            </button>
            <button
              type="button"
              onClick={quickLoginTenant}
              disabled={busy}
              className="flex items-center justify-center gap-1.5 py-2.5 px-3 bg-blue-50 hover:bg-blue-100 border border-blue-200 rounded-xl text-blue-800 text-xs font-semibold transition-all active:scale-95"
            >
              <User size={14} className="text-blue-700" />
              <span>Penghuni (K-204)</span>
            </button>
          </div>
        </div>
      </motion.div>
    </div>
  );
}
